previewCss:
.darma-loader-darma-b16-trumpet-valves { --accent: var(--loader-color, #ca8a04); --accent-2: var(--loader-secondary-color, #fef08a); width: var(--loader-size, 126px); height: calc(var(--loader-size, 126px) * .6); position: relative; }
.darma-loader-darma-b16-trumpet-valves .darma-loader-darma-b16-trumpet-valves__pipe { position: absolute; left: 6%; top: 44%; width: 68%; height: 14%; border-radius: 4px; background: linear-gradient(var(--accent-2), var(--accent)); }
.darma-loader-darma-b16-trumpet-valves .darma-loader-darma-b16-trumpet-valves__bell { position: absolute; right: 2%; top: 26%; width: 26%; height: 50%; border-radius: 10% 50% 50% 10% / 10% 50% 50% 10%; background: linear-gradient(90deg, var(--accent), color-mix(in srgb, #fff 35%, var(--accent-2))); }
.darma-loader-darma-b16-trumpet-valves span { position: absolute; top: 12%; width: 9%; height: 34%; border-radius: 4px 4px 2px 2px; background: linear-gradient(#e2e8f0, #94a3b8); transform-origin: 50% 100%; animation: darma-loader-darma-b16-trumpet-valves-valve-press calc(var(--loader-speed, 1s) * 1.5) ease-in-out infinite; }
.darma-loader-darma-b16-trumpet-valves span:nth-of-type(1) { left: 20%; }
.darma-loader-darma-b16-trumpet-valves span:nth-of-type(2) { left: 34%; animation-delay: calc(var(--loader-speed, 1s) * .25); }
.darma-loader-darma-b16-trumpet-valves span:nth-of-type(3) { left: 48%; animation-delay: calc(var(--loader-speed, 1s) * .5); }
@keyframes darma-loader-darma-b16-trumpet-valves-valve-press { 0%, 100% { transform: translateY(0) scaleY(1); } 14% { transform: translateY(26%) scaleY(.72); } 34% { transform: translateY(0) scaleY(1); } }

